diff --git a/powershell/internal/services/ad/queries/Get-MtLdapConfigurationContainer.ps1 b/powershell/internal/services/ad/queries/Get-MtLdapConfigurationContainer.ps1
index ef341ea54..acfc55750 100644
--- a/powershell/internal/services/ad/queries/Get-MtLdapConfigurationContainer.ps1
+++ b/powershell/internal/services/ad/queries/Get-MtLdapConfigurationContainer.ps1
@@ -91,6 +91,12 @@
         WellKnownSecurityPrincipals = @($wellKnown); SiteLinks = @($siteLinks); DhcpServers = @($dhcp); AuthNPolicyContainers = @($authN)
         TrustedRootCAs = @($trustedRoots); IntermediateCAs = @($intermediate); EnterpriseCAs = @($enterprise); CertificateTemplates = @($templates)
         EnrollmentTemplates = $enrollmentTemplates; CrlDistributionPoints = @($cdp); NtAuthCertificates = @($ntAuth); LdapQueryPolicies = @($policies)
+        # Whether the Directory Service object itself came back. It is NOT proof that
+        # tombstoneLifetime was readable: if the account can see the object but has no read
+        # access to that attribute, Active Directory omits the attribute and returns the
+        # object, which looks exactly like the attribute not being set. Callers must not
+        # infer a value from this flag alone - see Test-MtAdTombstoneLifetime.
+        DirectoryServiceRead = ($null -ne $directoryService)
         TombstoneLifetime = if ($null -ne $directoryService) { $directoryService.tombstoneLifetime } else { $null }
         DsHeuristics = if ($null -ne $directoryService) { $directoryService.dSHeuristics } else { $null }
         SpnMappings = if ($null -ne $directoryService) { @($directoryService.sPNMappings | Where-Object { $null -ne $_ }) } else { @() }
diff --git a/powershell/tests/functions/FalsePassOnEmptySource.Tests.ps1 b/powershell/tests/functions/FalsePassOnEmptySource.Tests.ps1
new file mode 100644
index 000000000..0804c1c0b
--- /dev/null
+++ b/powershell/tests/functions/FalsePassOnEmptySource.Tests.ps1
@@ -0,0 +1,106 @@
+﻿Describe 'Checks that must not pass when their data source returns nothing' {
+    BeforeAll {
+        Import-Module $PSScriptRoot/../../Maester.psd1 -Force
+        . "$PSScriptRoot/../helpers/Use-MtModuleFunction.ps1"
+        # A native test, so the function is not exported.
+        Use-MtModuleFunction -Name Test-MtAdTombstoneLifetime
+    }
+
+    BeforeEach {
+        $script:TestResult = $null
+        $script:SkippedBecause = $null
+
+        Mock -ModuleName Maester Get-MtLicenseInformation { return $true }
+        Mock -ModuleName Maester Add-MtTestResultDetail {
+            param($Result, $SkippedBecause)
+
+            $script:TestResult = $Result
+            $script:SkippedBecause = $SkippedBecause
+        }
+    }
+
+    Context 'AD-FOR-03 tombstone lifetime' {
+        It 'fails with the unable-to-retrieve message when the lifetime cannot be read' {
+            # The value used to be replaced with 180, which made the condition impossible to fail
+            # and reported a forest as retaining deleted objects for 180 days on an invented number.
+            Mock -ModuleName Maester Get-MtADDomainState {
+                [pscustomobject]@{
+                    Configuration = [pscustomobject]@{ TombstoneLifetime = $null }
+                    Forest        = [pscustomobject]@{ Name = 'contoso.com' }
+                }
+            }
+
+            Test-MtAdTombstoneLifetime | Should -BeFalse
+            $script:TestResult | Should -Match 'Unable to retrieve tombstone lifetime'
+        }
+
+        It 'does not invent a lifetime of 180 days when the value is missing' {
+            # DirectoryServiceRead false: the Directory Service object was not read at all, so
+            # there is no effective lifetime to report. This is the genuine retrieval failure.
+            Mock -ModuleName Maester Get-MtADDomainState {
+                [pscustomobject]@{
+                    Configuration = [pscustomobject]@{ TombstoneLifetime = $null; DirectoryServiceRead = $false }
+                    Forest        = [pscustomobject]@{ Name = 'contoso.com' }
+                }
+            }
+
+            $null = Test-MtAdTombstoneLifetime
+            $script:TestResult | Should -Not -Match '180 days'
+            $script:TestResult | Should -Not -Match 'Meets recommendation'
+        }
+
+        It 'does not pass on an inferred 60 days when the attribute is absent' {
+            # @merill asked for the "not set" case to say Active Directory then uses 60 days, and
+            # it does. @coderabbitai then pointed out that seeing the object is not proof the
+            # attribute was readable: an account without read access to tombstoneLifetime gets the
+            # object back with the attribute omitted, which is identical to it not being set. So
+            # the 60 days is explained, both causes are named, and the check still does not pass -
+            # inferring a value it never read is the false pass this file exists to prevent.
+      

... [1422 characters truncated] ...

ame Maester Get-MtADDomainState {
+                [pscustomobject]@{
+                    Configuration = [pscustomobject]@{ TombstoneLifetime = 60 }
+                    Forest        = [pscustomobject]@{ Name = 'contoso.com' }
+                }
+            }
+
+            $null = Test-MtAdTombstoneLifetime
+            $script:TestResult | Should -Match 'Below recommendation'
+        }
+
+        It 'skips when Active Directory is not reachable at all' {
+            Mock -ModuleName Maester Get-MtADDomainState { return $null }
+
+            $null -eq (Test-MtAdTombstoneLifetime) | Should -BeTrue
+            $script:SkippedBecause | Should -Be 'NotConnectedActiveDirectory'
+        }
+    }
+}
diff --git a/tests/ad/domain/Test.AD-FOR-03.ps1 b/tests/ad/domain/Test.AD-FOR-03.ps1
index 45f4d9806..1564bb0b3 100644
--- a/tests/ad/domain/Test.AD-FOR-03.ps1
+++ b/tests/ad/domain/Test.AD-FOR-03.ps1
@@ -51,14 +51,29 @@

     # Default values: 60 days for older forests, 180 days for newer forests
     $defaultValue = 180
-    if ($null -eq $tombstoneLifetime) {
-        $tombstoneLifetime = $defaultValue
-        $isDefault = $true
-    } else {
-        $isDefault = $false
-    }

-    # Test passes if we successfully retrieved tombstone lifetime
+    # The unreadable value used to be replaced with $defaultValue here. That made the condition
+    # below impossible to fail and left the "Unable to retrieve" branch unreachable, so a forest
+    # whose tombstone lifetime could not be read was reported as retaining deleted objects for 180
+    # days and as meeting the recommendation, on a number this test supplied itself. Worse, the
+    # substituted 180 is only the default for newer forests; an older forest defaults to 60, so the
+    # invented value could also claim the recommendation was met when it was not.
+    #
+    # Without the substitution the branch the author wrote for that case is the one that runs, which
+    # is what the title of this check asserts: the tombstone lifetime should be retrievable.
+
+    # A $null lifetime has two causes and LDAP does not let us tell them apart. @merill asked
+    # for the "not set" case to report the 60 days Active Directory then uses, and that is
+    # worth saying. But @coderabbitai is right that seeing the Directory Service object is not
+    # proof the attribute was readable: an account without read access to tombstoneLifetime
+    # gets the object back with the attribute omitted, which is byte-for-byte what "not set"
+    # looks like. Passing on a value inferred from that would be the same false pass this
+    # check exists to remove, so the reading is reported and the check still does not pass.
+    $directoryServiceRead = [bool]$adState.Configuration.DirectoryServiceRead
+    $notSetLifetime = 60
+    $isAbsent = $directoryServiceRead -and $null -eq $tombstoneLifetime
+
+    # Passes only when the forest actually returned a lifetime.
     $testResult = $null -ne $tombstoneLifetime

     # Generate markdown results
@@ -66,8 +81,7 @@
         $result = "| Property | Value |" + "`n"
         $result += "| --- | --- |" + "`n"
         $result += "| Tombstone Lifetime | $tombstoneLifetime days |" + "`n"
-        $result += "| Default Value | $defaultValue days |" + "`n"
-        $result += "| Using Default | $isDefault |" + "`n"
+        $result += "| Recommended minimum | $defaultValue days |" + "`n"
         $result += "| Forest Name | $($adState.Forest.Name) |" + "`n"

         $recommendation = if ($tombstoneLifetime -ge 180) { "✅ Meets recommendation (180+ days)" } else { "⚠️ Below recommendation (180 days)" }
@@ -76,7 +90,11 @@
         $testResultMarkdown = "The Active Directory tombstone lifetime has been retrieved. Deleted objects are retained for $tombstoneLifetime days before permanent removal.`n`n%TestResult%"
         $testResultMarkdown = $testResultMarkdown -replace "%TestResult%", $result
     } else {
-        $testResultMarkdown = "Unable to retrieve tombstone lifetime. Ensure you have appropriate permissions and the Active Directory module is installed."
+        $testResultMarkdown = if ($isAbsent) {
+            "The Directory Service object was read, but it carries no ``tombstoneLifetime``. That is either because the forest never set one - in which case Active Directory uses $notSetLifetime days, below the 180-day recommendation - or because this account cannot read the attribute. Active Directory returns the object with the attribute omitted in both cases, so the two cannot be told apart from here, and this check does not report a lifetime it did not read. Grant read access to ``tombstoneLifetime`` on CN=Directory Service,CN=Windows NT,CN=Services to settle which it is."
+        } else {
+            "Unable to retrieve tombstone lifetime. Ensure you have appropriate permissions and the Active Directory module is installed."
+        }
     }

     Add-MtTestResultDetail -Result $testResultMarkdown
