 15	    .LINK
 16	        https://maester.dev/docs/tests/CIS.M365.2.1.10
 17	    #>
 18	    [MaesterTest(
 19	        Id = 'CIS.M365.2.1.10',
 20	        Title = 'Ensure DMARC records for all Exchange Online domains are published',
 21	        Product = 'defender',
 22	        Feature = 'email-authentication',
 23	        Area = 'email-protection',
 24	        ResourceType = 'Domain',
 25	        Severity = 'Medium',
 26	        UserImpact = 'Low',
 27	        ImplementationCost = 'Medium',
 28	        Mitre = ('T1566', 'T1684.002'),
 29	        Control = ('cis-m365:2.1.10', 'nist-800-53-r5:SI-8'),
 30	        Service = 'ExchangeOnline',
 31	        Author = 'JeremyFinney-lgtm'
 32	    )]
 33	    [CmdletBinding()]
 34	    [OutputType([bool])]
 35	    param(
 36	        # Domains explicitly confirmed as parked; the parked DMARC audit still applies.
 37	        [string[]]$ParkedDomains = @()
 38	    )
 39	
 40	    Write-Verbose 'Getting accepted domains...'
 41	    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.IsCoExistenceDomain -eq $false })
 42	    $dkimSigningConfigs = @(Get-MtExo -Request DkimSigningConfig)
 43	
 44	    $report = foreach ($domain in $domains) {
 45	        $name = $domain.DomainName
 46	        $classification = Get-MtCisParkedDomainClassification -DomainName $name -DkimSigningConfigs $dkimSigningConfigs -ParkedDomains $ParkedDomains
 47	        $dmarc = $null
 48	        $source = $null
 49	        $unavailable = $false
 50	        $invalidCandidate = $null
 51	        # DMARC policy discovery uses the domain, then its organisational domain only.
 52	        $candidates = @($name, (Get-MtRegistrableDomain -DomainName $name)) | Select-Object -Unique
 53	        foreach ($candidate in $candidates) {
 54	            $found = ConvertFrom-MailAuthenticationRecordDmarc -DomainName $candidate
 55	            if ($found -is [string]) {
 56	                if ($found -like '*not available' -or $found -eq 'DNS lookup unavailable') { $unavailable = $true; break }
 57	                if ($found -eq 'Invalid DMARC record') { $invalidCandidate = $candidate }
 58	                continue
 59	            }
 60	            if ($null -ne $found -and $found -isnot [string]) {
 61	                $dmarc = $found
 62	                $source = $candidate
 63	                break
 64	            }
 65	        }
 66	        if ($unavailable) {
 67	            [pscustomobject]@{ Domain = $name; Classification = $classification.Classification; Policy = 'Not checked'; Source = 'None'; Failed = 'DNS lookup not available'; Pass = $null; Investigate = $false }
 68	            continue
 69	        }
 70	        $policy = $null
 71	        if ($dmarc) {
 72	            $policy = if ($source -ne $name -and $dmarc.policySubdomain) { $dmarc.policySubdomain } else { $dmarc.policy }
 73	        }
 74	        $sendingChecks = [ordered]@{
 75	            'Record is valid' = $null -ne $dmarc -and $dmarc.valid
 76	            'Policy is quarantine or reject' = $policy -in @('quarantine', 'reject')
 77	            'Applies to 100 percent' = $null -eq $dmarc -or $dmarc.percentage -eq 100 -or $null -eq $dmarc.percentage
 78	            'Aggregate reports (rua)' = @($dmarc.reportAggregate | Where-Object { $_.mailAddress }).Count -gt 0
 79	            'Forensic reports (ruf)' = @($dmarc.reportForensic | Where-Object { $_.mailAddress }).Count -gt 0
 80	        }
 81	        $nonSendingChecks = [ordered]@{
 82	            'Record is valid' = $null -ne $dmarc -and $dmarc.valid
 83	            'Parked-domain policy is reject' = $policy -eq 'reject'
 84	        }
 85	        $sendingFailures = @($sendingChecks.GetEnumerator() | Where-Object { -not $_.Value } | ForEach-Object { $_.Key })
 86	        $nonSendingFailures = @($nonSendingChecks.GetEnumerator() | Where-Object { -not $_.Value } | ForEach-Object { $_.Key })
 87	        $failedChecks = @()
 88	        $investigate = $false
 89	        if ($classification.Classification -in @('Parked', 'NotSending')) {
 90	            $failedChecks = $nonSendingFailures
 91	            $pass = $failedChecks.Count -eq 0
 92	        } elseif ($classification.Classification -eq 'Unknown') {
 93	            if ($sendingFailures.Count -eq 0 -and $nonSendingFailures.Count -eq 0) {
 94	                $pass = $true
 95	            } elseif ($sendingFailures.Count -eq 0 -or $nonSendingFailures.Count -eq 0) {
 96	                $pass = $true
 97	                $investigate = $true
 98	                $failedChecks = if ($sendingFailures.Count -eq 0) {
 99	                    @("If parked or non-sending: $($nonSendingFailures -join ', ')")
100	                } else {
101	                    @("If sending: $($sendingFailures -join ', ')")
102	                }
103	            } else {
104	                $pass = $false
105	                $failedChecks = @(
106	                    @($sendingFailures | ForEach-Object { "If sending: $_" }) +
107	                    @($nonSendingFailures | ForEach-Object { "If parked or non-sending: $_" })
108	                )
109	            }
110	        } else {
111	            $failedChecks = $sendingFailures
112	            $pass = $failedChecks.Count -eq 0
113	        }
114	        [pscustomobject]@{
115	            Domain         = $name
116	            Classification = $classification.Classification
117	            Policy         = if ($policy) { $policy } elseif ($invalidCandidate) { 'Invalid DMARC record' } else { 'No valid record' }
118	            Source         = if ($source) { $source } elseif ($invalidCandidate) { $invalidCandidate } else { 'None' }
119	            Failed         = $failedChecks -join ', '
120	            Pass           = $pass
121	            Investigate    = $investigate
122	        }
123	    }
124	    $checked = @($report | Where-Object { $null -ne $_.Pass })
125	    $unchecked = @($report | Where-Object { $null -eq $_.Pass -and -not $_.Investigate })
126	    $failed = @($checked | Where-Object { -not $_.Pass })
127	    $investigated = @($report | Where-Object { $_.Investigate })
128	    if ($failed.Count -eq 0 -and $unchecked.Count -gt 0 -and $investigated.Count -eq 0) {
129	        Add-MtTestResultDetail -SkippedBecause NotSupported
130	        return $null
131	    }
132	    $testResult = $failed.Count -eq 0
133	
134	    $passText = 'All accepted domains meet the applicable CIS DMARC requirement.'
135	    $failText = "$($failed.Count) domain(s) do not have a compliant DMARC policy."
136	
137	    $resultMd = "| Domain | Classification | Applied policy | Record found at | Failed checks | Result |`n"
138	    $resultMd += "| --- | --- | --- | --- | --- | --- |`n"
139	    foreach ($row in $report) {
140	        $resultText = if ($row.Investigate) { 'Investigate' } elseif ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }
141	        $resultMd += "| $($row.Domain) | $($row.Classification) | $($row.Policy) | $($row.Source) | $(if ($row.Failed) { $row.Failed } else { 'None' }) | $resultText |`n"
142	    }
143	
144	    if ($testResult -and ($investigated.Count -gt 0 -or $unchecked.Count -gt 0)) {
145	        $testResultMarkdown = "Compliance with the applicable CIS DMARC requirement remains unconfirmed. Review the domains marked Investigate or Not checked.`n`n%TestResult%"
146	    }
147	    elseif ($testResult) {
148	        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
149	    } else {
150	        $testResultMarkdown = "$failText`n`n%TestResult%"
151	    }
152	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd
153	
154	    Add-MtTestResultDetail -Result $testResultMarkdown -Investigate:($investigated.Count -gt 0 -and $failed.Count -eq 0)
155	    return $testResult
156	}

