     2	    <#
     3	    .SYNOPSIS
     4	    Checks DKIM for domains that send email and verifies parked domains have no DKIM records.
     5	
     6	    .DESCRIPTION
     7	    Sending domains require DKIM to be enabled with a valid Exchange status. Parked domains must not publish DKIM records. Initial (MOERA) and coexistence domains are excluded, as Microsoft automatically signs outbound mail for those domains. Ambiguous domain-use evidence is reported for investigation.
     8	    CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.9, L1)
     9	
    10	    .EXAMPLE
    11	    Test-MtCisDkim
    12	
    13	    Returns true if every sending domain has DKIM enabled with Exchange status Valid and every parked domain has no known Exchange selector records. Initial and coexistence domains are excluded. Domains classified as not sending are out of scope; ambiguous domains require investigation.
    14	
    15	    .LINK
    16	    https://maester.dev/docs/commands/Test-MtCisDkim
    17	    #>
    18	    [MaesterTest(
    19	        Id = 'CIS.M365.2.1.9',
    20	        Title = 'Ensure that DKIM is enabled for all Exchange Online Domains',
    21	        Product = 'defender',
    22	        RelatedProduct = 'exchange',
    23	        Feature = 'email-authentication',
    24	        Area = 'email-protection',
    25	        ResourceType = 'Domain',
    26	        Severity = 'Medium',
    27	        UserImpact = 'Low',
    28	        ImplementationCost = 'Medium',
    29	        Mitre = ('T1566', 'T1684.002'),
    30	        Control = ('cis-m365:2.1.9', 'nist-800-53-r5:SC-8'),
    31	        Service = 'ExchangeOnline',
    32	        Author = 'NZLostboy',
    33	        Contributor = ('JeanPhilippeGeorge', 'brianreidc7', 'amlhive-tech', 'JeremyFinney-lgtm')
    34	    )]
    35	    [CmdletBinding()]
    36	    [OutputType([bool])]
    37	    param(
    38	        # Selector-name for the DKIM record to test..
    39	        [string]$Selector = 'selector1',
    40	
    41	        # Domains explicitly confirmed as parked; any published selector record still fails the audit.
    42	        [string[]]$ParkedDomains = @()
    43	    )
    44	
    45	    $dkimSigningConfigs = Get-MtExo -Request DkimSigningConfig
    46	    $acceptedDomains = Get-MtExo -Request AcceptedDomain
    47	
    48	    $dkimRecords = @()
    49	    foreach ($domain in $acceptedDomains) {
    50	        if ($domain.InitialDomain -eq $true -or $domain.IsCoExistenceDomain -eq $true) {
    51	            $dkimRecord = [PSCustomObject]@{
    52	                domain     = $domain.DomainName
    53	                classification = 'Excluded'
    54	                pass       = 'Skipped'
    55	                reason     = 'Initial or coexistence domain excluded from DKIM audit (Microsoft auto-signs outbound mail for this domain)'
    56	                exchangeStatus = 'Excluded'
    57	                dkimRecord = $null
    58	            }
    59	            $dkimRecords += $dkimRecord
    60	            continue
    61	        }
    62	
    63	        $classification = Get-MtCisParkedDomainClassification -DomainName $domain.DomainName -DkimSigningConfigs $dkimSigningConfigs -ParkedDomains $ParkedDomains
    64	        if ($classification.Classification -eq 'Parked') {
    65	            $hasDkimSelectorRecord = $classification.DkimSelectorRecordEvidence
    66	            $selectorLookupsComplete = $classification.DkimSelectorLookupsComplete
    67	            $dkimRecords += [PSCustomObject]@{
    68	                domain         = $domain.DomainName
    69	                classification = $classification.Classification
    70	                pass           = if ($hasDkimSelectorRecord) { 'Failed' } elseif (-not $selectorLookupsComplete) { 'Investigate' } else { 'Passed' }
    71	                reason         = if ($hasDkimSelectorRecord) { "Parked domain has a published standard DKIM selector record that must be removed. $($classification.Reason)" } elseif (-not $selectorLookupsComplete) { "Standard DKIM selector DNS lookups did not complete, so record absence could not be confirmed. $($classification.Reason)" } else { "Parked domain has no published standard DKIM selector records. $($classification.Reason)" }
    72	                exchangeStatus = if ($selectorLookupsComplete) { 'Not applicable' } else { 'Not determined' }
    73	                dkimRecord     = $null
    74	            }
    75	            continue
    76	        }
    77	
    78	        if ($classification.Classification -eq 'NotSending') {
    79	            $dkimRecords += [PSCustomObject]@{
    80	                domain         = $domain.DomainName
    81	                classification = $classification.Classification
    82	                pass           = 'Skipped'
    83	                reason         = "The CIS DKIM audit applies to domains configured to send email. $($classification.Reason)"
    84	                exchangeStatus = 'Not applicable'
    85	                dkimRecord     = $null
    86	            }
    87	            continue
    88	        }
    89	
    90	        if ($classification.Classification -eq 'Unknown') {
    91	            if ($classification.DnsResolverUnavailable) {
    92	                $dkimRecords += [PSCustomObject]@{
    93	                    domain         = $domain.DomainName
    94	                    classification = $classification.Classification
    95	                    pass           = 'NotSupported'
    96	                    reason         = "DNS resolver is unavailable, so sending use and selector records cannot be evaluated. $($classification.Reason)"
    97	                    exchangeStatus = 'Not determined'
    98	                    dkimRecord     = $null
    99	                }
   100	                continue
   101	            }
   102	
   103	            $dkimRecords += [PSCustomObject]@{
   104	                domain         = $domain.DomainName
   105	                classification = $classification.Classification
   106	                pass           = 'Investigate'
   107	                reason         = "Sending use could not be established; the domain was not classified as parked. $($classification.Reason)"
   108	                exchangeStatus = 'Not determined'
   109	                dkimRecord     = $null
   110	            }
   111	            continue
   112	        }
   113	
   114	        $dkimSigningConfig = $dkimSigningConfigs | Where-Object {
   115	            $_.domain -eq $domain.domainname
   116	        }
   117	
   118	        if (-not $dkimSigningConfig) {
   119	            $dkimRecord = [PSCustomObject]@{
   120	                domain     = $domain.DomainName
   121	                classification = $classification.Classification
   122	                pass       = 'Failed'
   123	                reason     = 'No DkimSigningConfig found for a domain classified as sending'
   124	                exchangeStatus = 'Not configured'
   125	                dkimRecord = $null
   126	            }
   127	            $dkimRecords += $dkimRecord
   128	            continue
   129	        }
   130	
   131	        if ((Get-Date) -gt $dkimSigningConfig.RotateOnDate) {
   132	            if ($Selector -ne $dkimSigningConfig.SelectorAfterRotateOnDate) {
   133	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorAfterRotateOnDate) based on EXO config"
   134	            }
   135	            $Selector = $dkimSigningConfig.SelectorAfterRotateOnDate
   136	        } else {
   137	            if ($Selector -ne $dkimSigningConfig.SelectorBeforeRotateOnDate) {
   138	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorBeforeRotateOnDate) based on EXO config"
   139	            }
   140	            $selector = $dkimSigningConfig.SelectorBeforeRotateOnDate
   141	        }
   142	
   143	        $isMicrosoftDomain = $domain.DomainName.EndsWith(".onmicrosoft.com")
   144	        $isMicrosoftExoHybridDomain = $domain.DomainName.EndsWith(".mail.onmicrosoft.com")
   145	        $dkimDnsName = if ($isMicrosoftExoHybridDomain) {
   146	            "$($Selector)._domainkey.$($domain.DomainName)"
   147	        } elseif ($isMicrosoftDomain) {
   148	            $dkimSigningConfig."$($selector)CNAME"
   149	        } else {
   150	            "$($Selector)._domainkey.$($domain.DomainName)"
   151	        }
   152	        $dkimRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -DkimDnsName $dkimDnsName -Records DKIM
   153	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'pass' -Value 'Failed'
   154	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'reason' -Value ''
   155	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'exchangeStatus' -Value $dkimSigningConfig.Status
   156	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'classification' -Value $classification.Classification
   157	
   158	        if (-not $dkimSigningConfig.enabled) {
   159	            $dkimRecord.pass = 'Failed'
   160	            $dkimRecord.reason = 'DKIM is disabled'
   161	        } elseif ($dkimSigningConfig.Status -ne 'Valid') {
   162	            $dkimRecord.pass = 'Failed'
   163	            $dkimRecord.reason = "Exchange DKIM status is '$($dkimSigningConfig.Status)' (expected Valid)"
   164	        } elseif ($null -ne $dkimRecord.dkimRecord -and $dkimRecord.dkimRecord.GetType().Name -eq 'DKIMRecord') {
   165	            if (-not $dkimRecord.dkimRecord.validBase64) {
   166	                $dkimRecord.reason = 'Malformed public key'
   167	            } else {
   168	                $dkimRecord.pass = 'Passed'
   169	            }
   170	        } elseif ($domain.DomainName -like '*.onmicrosoft.com') {
   171	            $dkimRecord.reason = "Recommendation: Disable sending from domain"
   172	        } elseif ($dkimRecord.dkimRecord -like '*not available') {
   173	            $dkimRecord.pass = 'NotSupported'
   174	            $dkimRecord.reason = $dkimRecord.dkimRecord
   175	        } else {
   176	            $dkimRecord.reason = $dkimRecord.dkimRecord
   177	        }
   178	
   179	        $dkimRecords += $dkimRecord
   180	    }
   181	
   182	    if ('Failed' -in $dkimRecords.pass) {
   183	        $testResult = $false
   184	    }
   185	    elseif ('Investigate' -in $dkimRecords.pass) {
   186	        $testResult = $true
   187	    }
   188	    elseif ('NotSupported' -in $dkimRecords.pass -and 'Passed' -notin $dkimRecords.pass) {
   189	        Add-MtTestResultDetail -SkippedBecause NotSupported
   190	        return $null
   191	    }
   192	    elseif ('Passed' -notin $dkimRecords.pass) {
   193	        Add-MtTestResultDetail -SkippedBecause NotApplicable
   194	        return $null
   195	    }
   196	    else {
   197	        $testResult = $true
   198	    }
   199	
   200	    $portalLink = 'https://security.microsoft.com/authentication?viewid=DKIM'
   201	
   202	    if ($testResult -and ('Investigate' -in $dkimRecords.pass -or 'NotSupported' -in $dkimRecords.pass)) {
   203	        $testResultMarkdown = "Compliance with the applicable CIS DKIM requirement remains unconfirmed. Review the domains marked Investigate or skipped because DNS lookups are unavailable.`n`n%TestResult%"
   204	    }
   205	    elseif ($testResult) {
   206	        $testResultMarkdown = "Well done. Sending domains have DKIM configured and valid records exist, and parked domains have no known Exchange selector records.`n`n%TestResult%"
   207	    } else {
   208	        $testResultMarkdown = "Your tenant's domains do not have DKIM fully deployed. Review [EXO configuration]($portalLink) and DNS records.`n`n%TestResult%"
   209	    }
   210	
   211	    $passResult = '✅ Pass'
   212	    $failResult = '❌ Fail'
   213	    $skipResult = '🗄️ Skip'
   214	    $result = "| Domain | Classification | Result | Exchange status | Reason |`n"
   215	    $result += "| --- | --- | --- | --- | --- |`n"
   216	    foreach ($item in $dkimRecords | Sort-Object -Property domain) {
   217	        switch ($item.pass) {
   218	            'Passed' { $itemResult = $passResult }
   219	            'Skipped' { $itemResult = $skipResult }
   220	            'NotSupported' { $itemResult = $skipResult }
   221	            'Failed' { $itemResult = $failResult }
   222	            'Investigate' { $itemResult = '🔎 Investigate' }
   223	        }
   224	        $result += "| $($item.domain) | $($item.classification) | $($itemResult) | $($item.exchangeStatus) | $($item.reason) |`n"
   225	    }
   226	
   227	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $result
   228	
   229	    Add-MtTestResultDetail -Result $testResultMarkdown -Investigate:('Investigate' -in $dkimRecords.pass -and 'Failed' -notin $dkimRecords.pass)
   230	    return $testResult
   231	}
