     1	﻿function Test-MtCisSpfRecordsPublished {
     2	    <#
     3	    .SYNOPSIS
     4	        Checks the applicable CIS SPF requirement for each custom accepted domain.
     5	
     6	    .DESCRIPTION
     7	        Sending domains must publish an SPF record that ends with -all or ~all, directly or through a redirect. Parked or otherwise non-sending domains must publish an SPF policy that denies all senders with -all. Domains in the onmicrosoft.com namespace are excluded because Microsoft manages their SPF. Ambiguous domain-use evidence is reported for investigation rather than receiving the parked-domain exception.
     8	        CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.8, L1)
     9	
    10	    .EXAMPLE
    11	        Test-MtCisSpfRecordsPublished
    12	
    13	        Returns true if all custom domains meet the applicable CIS SPF requirement.
    14	
    15	    .LINK
    16	        https://maester.dev/docs/tests/CIS.M365.2.1.8
    17	    #>
    18	    [MaesterTest(
    19	        Id = 'CIS.M365.2.1.8',
    20	        Title = 'Ensure that SPF records are published for all Exchange Domains',
    21	        Product = 'defender',
    22	        Feature = 'email-authentication',
    23	        Area = 'email-protection',
    24	        ResourceType = 'Domain',
    25	        Severity = 'Medium',
    26	        UserImpact = 'Low',
    27	        ImplementationCost = 'Medium',
    28	        Mitre = ('T1566', 'T1684.002'),
    29	        Control = ('cis-m365:2.1.8', 'nist-800-53-r5:SI-8'),
    30	        Service = 'ExchangeOnline',
    31	        Author = 'JeremyFinney-lgtm'
    32	    )]
    33	    [CmdletBinding()]
    34	    [OutputType([bool])]
    35	    param(
    36	        # Domains explicitly confirmed as parked; the parked SPF audit still applies.
    37	        [string[]]$ParkedDomains = @()
    38	    )
    39	
    40	    Write-Verbose 'Getting accepted domains...'
    41	    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.InitialDomain -eq $false -and $_.IsCoExistenceDomain -eq $false })
    42	    $dkimSigningConfigs = @(Get-MtExo -Request DkimSigningConfig)
    43	
    44	    $report = foreach ($domain in $domains) {
    45	        $name = $domain.DomainName
    46	        $classification = Get-MtCisParkedDomainClassification -DomainName $name -DkimSigningConfigs $dkimSigningConfigs -ParkedDomains $ParkedDomains
    47	        $detail = ''
    48	        $spf = ConvertFrom-MailAuthenticationRecordSpf -DomainName $name
    49	        if ($spf -is [string] -and ($spf -like '*not available' -or $spf -eq 'DNS lookup unavailable')) {
    50	            [pscustomobject]@{ Domain = $name; Record = $null; Classification = $classification.Classification; Pass = $null; Investigate = $false; Detail = 'DNS lookup not available' }
    51	            continue
    52	        }
    53	        $record = if ($spf -and $spf.PSObject.Properties['record']) { $spf.record } else { $null }
    54	        $effective = $record
    55	        $redirectTargets = @()
    56	        $redirectError = $null
    57	        $redirectUnavailable = $false
    58	        $visitedDomains = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    59	        $null = $visitedDomains.Add($name)
    60	
    61	        while ($effective) {
    62	            # RFC 7208 section 5.1: a redirect is ignored when the record has an all mechanism.
    63	            $localAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all(\s|$)')
    64	            if ($localAll.Success) { break }
    65	
    66	            $redirect = [regex]::Match([string]$effective, '(?i)(?:^|\s)redirect=(?<target>[^\s;]+)')
    67	            if (-not $redirect.Success) { break }
    68	            $target = $redirect.Groups['target'].Value
    69	
    70	            if ($redirectTargets.Count -ge 9) {
    71	                $redirectError = 'The redirect chain exceeds the DNS lookup limit.'
    72	                break
    73	            }
    74	            if (-not $visitedDomains.Add($target)) {
    75	                $redirectError = "The redirect chain contains a cycle at $target."
    76	                break
    77	            }
    78	
    79	            $redirectTargets += $target
    80	            $redirected = ConvertFrom-MailAuthenticationRecordSpf -DomainName $target
    81	            if ($redirected -is [string] -and ($redirected -like '*not available' -or $redirected -eq 'DNS lookup unavailable')) {
    82	                $redirectUnavailable = $true
    83	                break
    84	            }
    85	            $effective = if ($null -ne $redirected -and $redirected.PSObject.Properties['record']) { $redirected.record } else { $null }
    86	            if (-not $effective) {
    87	                $redirectError = "No SPF record was found at redirect target $target."
    88	                break
    89	            }
    90	        }
    91	
    92	        if ($redirectUnavailable) {
    93	            [pscustomobject]@{ Domain = $name; Record = $record; Classification = $classification.Classification; Pass = $null; Investigate = $false; Detail = "DNS lookup not available for $($redirectTargets[-1])" }
    94	            continue
    95	        }
    96	        $effectiveAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all\s*$')
    97	        $sendingDomainPass = $effectiveAll.Success -and $effectiveAll.Groups['q'].Value -in '-', '~'
    98	        $pass = $sendingDomainPass
    99	        $investigate = $false
   100	        if (-not $record) {
   101	            $detail = 'No SPF record found'
   102	        } elseif ($redirectError) {
   103	            $detail = $redirectError
   104	        } elseif ($redirectTargets.Count -gt 0 -and -not $pass) {
   105	            $detail = "The effective record after redirecting to $($redirectTargets -join ' -> ') does not end with -all or ~all"
   106	        } elseif ($redirectTargets.Count -gt 0) {
   107	            $detail = "Redirects to $($redirectTargets -join ' -> ')"
   108	        }
   109	        elseif (-not $pass) {
   110	            $detail = 'The record does not end with -all or ~all'
   111	        }
   112	
   113	        if ($classification.Classification -in @('Parked', 'NotSending')) {
   114	            $pass = $classification.SpfDeniesAll
   115	            $detail = if ($pass) {
   116	                'The parked/non-sending audit requires an SPF record that explicitly denies all senders; this record uses -all.'
   117	            } else {
   118	                'The parked/non-sending audit requires an SPF record that explicitly denies all senders with -all.'
   119	            }
   120	        } elseif ($classification.Classification -eq 'Unknown' -and $sendingDomainPass -and -not $classification.SpfDeniesAll) {
   121	            $pass = $null
   122	            $investigate = $true
   123	            $detail = 'The sending-domain SPF audit passes, but the available evidence cannot rule out the parked-domain requirement for -all.'
   124	        } elseif ($classification.Classification -eq 'Unknown' -and $sendingDomainPass) {
   125	            $pass = $true
   126	            $detail = 'The record meets both the sending-domain and parked-domain SPF requirements.'
   127	        }
   128	
   129	        $detail = "$($classification.Reason) $detail"
   130	        [pscustomobject]@{ Domain = $name; Record = $record; Classification = $classification.Classification; Pass = $pass; Investigate = $investigate; Detail = $detail }
   131	    }
   132	
   133	    $unchecked = @($report | Where-Object { $null -eq $_.Pass -and -not $_.Investigate })
   134	    $failed = @($report | Where-Object { $_.Pass -eq $false })
   135	    $investigated = @($report | Where-Object { $_.Investigate })
   136	    if ($failed.Count -gt 0) {
   137	        $testResult = $false
   138	    } elseif ($unchecked.Count -gt 0 -and $investigated.Count -eq 0) {
   139	        Add-MtTestResultDetail -SkippedBecause NotSupported
   140	        return $null
   141	    } else {
   142	        $testResult = $true
   143	    }
   144	
   145	    $passText = if ($domains.Count -eq 0) { 'There are no custom domains, so no SPF records are required.' } else { 'All custom domains meet the applicable CIS SPF requirement.' }
   146	    $failText = "$($failed.Count) custom domain(s) do not meet the applicable CIS SPF requirement."
   147	
   148	    $resultMd = "| Domain | Classification | SPF record | Detail | Result |`n"
   149	    $resultMd += "| --- | --- | --- | --- | --- |`n"
   150	    foreach ($row in $report) {
   151	        $resultText = if ($null -eq $row.Pass -and $row.Investigate) { 'Investigate' } elseif ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }
   152	        $resultMd += "| $($row.Domain) | $($row.Classification) | $($row.Record) | $($row.Detail) | $resultText |`n"
   153	    }
   154	
   155	    if ($testResult -and ($investigated.Count -gt 0 -or $unchecked.Count -gt 0)) {
   156	        $testResultMarkdown = "Compliance with the applicable CIS SPF requirement remains unconfirmed. Review the domains marked Investigate or Not checked.`n`n%TestResult%"
   157	    }
   158	    elseif ($testResult) {
   159	        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
   160	    }
   161	    else {
   162	        $testResultMarkdown = "$failText`n`n%TestResult%"
   163	    }
   164	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd
   165	
   166	    Add-MtTestResultDetail -Result $testResultMarkdown -Investigate:($investigated.Count -gt 0 -and $failed.Count -eq 0)
   167	    return $testResult
   168	}
