function Test-MtCisDkim {
    <#
    .SYNOPSIS
    Checks DKIM for domains that send email and verifies parked domains have no DKIM records.

    .DESCRIPTION
    Domains require DKIM to be enabled with a valid Exchange status. Domains listed in the ParkedDomains parameter must not publish DKIM records instead. Initial (MOERA) and coexistence domains are excluded, as Microsoft automatically signs outbound mail for those domains.
    CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.9, L1)

    .EXAMPLE
    Test-MtCisDkim

    Returns true if every domain has DKIM enabled with Exchange status Valid, and every domain listed in ParkedDomains has no selector1 or selector2 DKIM record. Initial and coexistence domains are excluded.

    .LINK
    https://maester.dev/docs/commands/Test-MtCisDkim
    #>
    [MaesterTest(
        Id = 'CIS.M365.2.1.9',
        Title = 'Ensure that DKIM is enabled for all Exchange Online Domains',
        Product = 'defender',
        RelatedProduct = 'exchange',
        Feature = 'email-authentication',
        Area = 'email-protection',
        ResourceType = 'Domain',
        Severity = 'Medium',
        UserImpact = 'Low',
        ImplementationCost = 'Medium',
        Mitre = ('T1566', 'T1684.002'),
        Control = ('cis-m365:2.1.9', 'nist-800-53-r5:SC-8'),
        Service = 'ExchangeOnline',
        Author = 'NZLostboy',
        Contributor = ('JeanPhilippeGeorge', 'brianreidc7', 'amlhive-tech', 'JeremyFinney-lgtm')
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Selector-name for the DKIM record to test..
        [string]$Selector = 'selector1',

        # Domains that are not used to send email. They must not publish DKIM records.
        [string[]]$ParkedDomains = @()
    )

    $dkimSigningConfigs = Get-MtExo -Request DkimSigningConfig
    $acceptedDomains = Get-MtExo -Request AcceptedDomain

    $dkimRecords = @()
    foreach ($domain in $acceptedDomains) {
        if ($domain.InitialDomain -eq $true -or $domain.IsCoExistenceDomain -eq $true) {
            $dkimRecord = [PSCustomObject]@{
                domain     = $domain.DomainName
                classification = 'Excluded'
                pass       = 'Skipped'
                reason     = 'Initial or coexistence domain excluded from DKIM audit (Microsoft auto-signs outbound mail for this domain)'
                exchangeStatus = 'Excluded'
                dkimRecord = $null
            }
            $dkimRecords += $dkimRecord
            continue
        }

        if (Test-MtCisParkedDomain -DomainName $domain.DomainName -ParkedDomains $ParkedDomains) {
            # CIS: don't publish DKIM records for a parked domain. Exchange Online uses selector1 and selector2.
            $selectorLookups = foreach ($selectorName in 'selector1', 'selector2') {
                foreach ($recordType in 'CNAME', 'TXT') {
                    Resolve-MtDnsRecord -Name "$selectorName._domainkey.$($domain.DomainName)" -Type $recordType
                }
            }
            $hasSelectorRecord = @($selectorLookups | Where-Object { @($_.Answers).Count -gt 0 }).Count -gt 0
            $incompleteLookups = @($selectorLookups | Where-Object { $_.Status -notin @('Success', 'NXDomain') })
            $resolverUnavailable = @($selectorLookups | Where-Object { $_.Status -ne 'NotAvailable' }).Count -eq 0

            $pass, $reason = if ($hasSelectorRecord) {
                'Failed', 'Listed as parked, but a selector1 or selector2 DKIM record is published. Remove it.'
            } elseif ($resolverUnavailable) {
                'NotSupported', 'Listed as parked, but DNS lookups are not available here, so the DKIM records could not be checked.'
            } elseif ($incompleteLookups.Count -gt 0) {
                'Investigate', 'Listed as parked, but some DKIM selector lookups failed, so it could not be confirmed that no record is published.'
            } else {
                'Passed', 'Listed as parked, and no selector1 or selector2 DKIM record is published.'
            }
            $dkimRecords += [PSCustomObject]@{
                domain         = $domain.DomainName
                classification = 'Parked'
                pass           = $pass
                reason         = $reason
                exchangeStatus = 'Not applicable'
                dkimRecord     = $null
            }
            continue
        }

        $dkimSigningConfig = $dkimSigningConfigs | Where-Object {
            $_.domain -eq $domain.domainname
        }

        if (-not $dkimSigningConfig) {
            $dkimRecord = [PSCustomObject]@{
                domain     = $domain.DomainName
                classification = 'Sending'
                pass       = 'Failed'
                reason     = 'No DkimSigningConfig found. Add the domain to ParkedDomains if it does not send email.'
                exchangeStatus = 'Not configured'
                dkimRecord = $null
            }
            $dkimRecords += $dkimRecord
            continue
        }

        if ((Get-Date) -gt $dkimSigningConfig.RotateOnDate) {
            if ($Selector -ne $dkimSigningConfig.SelectorAfterRotateOnDate) {
                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorAfterRotateOnDate) based on EXO config"
            }
            $Selector = $dkimSigningConfig.SelectorAfterRotateOnDate
        } else {
            if ($Selector -ne $dkimSigningConfig.SelectorBeforeRotateOnDate) {
                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorBeforeRotateOnDate) based on EXO config"
            }
            $selector = $dkimSigningConfig.SelectorBeforeRotateOnDate
        }

        $isMicrosoftDomain = $domain.DomainName.EndsWith(".onmicrosoft.com")
        $isMicrosoftExoHybridDomain = $domain.DomainName.EndsWith(".mail.onmicrosoft.com")
        $dkimDnsName = if ($isMicrosoftExoHybridDomain) {
            "$($Selector)._domainkey.$($domain.DomainName)"
        } elseif ($isMicrosoftDomain) {
            $dkimSigningConfig."$($selector)CNAME"
        } else {
            "$($Selector)._domainkey.$($domain.DomainName)"
        }
        $dkimRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -DkimDnsName $dkimDnsName -Records DKIM
        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'pass' -Value 'Failed'
        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'reason' -Value ''
        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'exchangeStatus' -Value $dkimSigningConfig.Status
        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'classification' -Value 'Sending'

        if (-not $dkimSigningConfig.enabled) {
            $dkimRecord.pass = 'Failed'
            $dkimRecord.reason = 'DKIM is disabled'
        } elseif ($dkimSigningConfig.Status -ne 'Valid') {
            $dkimRecord.pass = 'Failed'
            $dkimRecord.reason = "Exchange DKIM status is '$($dkimSigningConfig.Status)' (expected Valid)"
        } elseif ($null -ne $dkimRecord.dkimRecord -and $dkimRecord.dkimRecord.GetType().Name -eq 'DKIMRecord') {
            if (-not $dkimRecord.dkimRecord.validBase64) {
                $dkimRecord.reason = 'Malformed public key'
            } else {
                $dkimRecord.pass = 'Passed'
            }
        } elseif ($domain.DomainName -like '*.onmicrosoft.com') {
            $dkimRecord.reason = "Recommendation: Disable sending from domain"
        } elseif ($dkimRecord.dkimRecord -like '*not available') {
            $dkimRecord.pass = 'NotSupported'
            $dkimRecord.reason = $dkimRecord.dkimRecord
        } else {
            $dkimRecord.reason = $dkimRecord.dkimRecord
        }

        $dkimRecords += $dkimRecord
    }

    if ('Failed' -in $dkimRecords.pass) {
        $testResult = $false
    }
    elseif ('Investigate' -in $dkimRecords.pass) {
        $testResult = $true
    }
    elseif ('NotSupported' -in $dkimRecords.pass -and 'Passed' -notin $dkimRecords.pass) {
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    }
    elseif ('Passed' -notin $dkimRecords.pass) {
        Add-MtTestResultDetail -SkippedBecause NotApplicable
        return $null
    }
    else {
        $testResult = $true
    }

    $portalLink = 'https://security.microsoft.com/authentication?viewid=DKIM'

    if ($testResult -and ('Investigate' -in $dkimRecords.pass -or 'NotSupported' -in $dkimRecords.pass)) {
        $testResultMarkdown = "Compliance with the applicable CIS DKIM requirement remains unconfirmed. Review the domains marked Investigate or skipped because DNS lookups are unavailable.`n`n%TestResult%"
    }
    elseif ($testResult) {
        $testResultMarkdown = "Well done. Sending domains have DKIM configured and valid records exist, and parked domains have no known Exchange selector records.`n`n%TestResult%"
    } else {
        $testResultMarkdown = "Your tenant's domains do not have DKIM fully deployed. Review [EXO configuration]($portalLink) and DNS records.`n`n%TestResult%"
    }

    $passResult = '✅ Pass'
    $failResult = '❌ Fail'
    $skipResult = '🗄️ Skip'
    $result = "| Domain | Classification | Result | Exchange status | Reason |`n"
    $result += "| --- | --- | --- | --- | --- |`n"
    foreach ($item in $dkimRecords | Sort-Object -Property domain) {
        switch ($item.pass) {
            'Passed' { $itemResult = $passResult }
            'Skipped' { $itemResult = $skipResult }
            'NotSupported' { $itemResult = $skipResult }
            'Failed' { $itemResult = $failResult }
            'Investigate' { $itemResult = '🔎 Investigate' }
        }
        $result += "| $($item.domain) | $($item.classification) | $($itemResult) | $($item.exchangeStatus) | $($item.reason) |`n"
    }

    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $result

    Add-MtTestResultDetail -Result $testResultMarkdown -Investigate:('Investigate' -in $dkimRecords.pass -and 'Failed' -notin $dkimRecords.pass)
    return $testResult
}

function Test-MtCisDmarcRecordsPublished {
    <#
    .SYNOPSIS
        Checks the applicable CIS DMARC requirement for each accepted domain.

    .DESCRIPTION
        Looks up the DMARC record that applies to each accepted domain, falling back to the organisational domain when the domain has no valid record, including a malformed record. Sending domains require quarantine or reject, 100 percent coverage, and mailto aggregate (rua) and forensic (ruf) report addresses. Domains listed in the ParkedDomains parameter require a valid record with p=reject. Every other domain gets the sending-domain audit.
        CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.10, L1)

    .EXAMPLE
        Test-MtCisDmarcRecordsPublished

        Returns true if all accepted domains meet the applicable CIS DMARC requirement.

    .LINK
        https://maester.dev/docs/tests/CIS.M365.2.1.10
    #>
    [MaesterTest(
        Id = 'CIS.M365.2.1.10',
        Title = 'Ensure DMARC records for all Exchange Online domains are published',
        Product = 'defender',
        Feature = 'email-authentication',
        Area = 'email-protection',
        ResourceType = 'Domain',
        Severity = 'Medium',
        UserImpact = 'Low',
        ImplementationCost = 'Medium',
        Mitre = ('T1566', 'T1684.002'),
        Control = ('cis-m365:2.1.10', 'nist-800-53-r5:SI-8'),
        Service = 'ExchangeOnline',
        Author = 'JeremyFinney-lgtm'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Domains that are not used to send email. They need a valid DMARC record with p=reject.
        [string[]]$ParkedDomains = @()
    )

    Write-Verbose 'Getting accepted domains...'
    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.IsCoExistenceDomain -eq $false })

    $report = foreach ($domain in $domains) {
        $name = $domain.DomainName
        $isParked = Test-MtCisParkedDomain -DomainName $name -ParkedDomains $ParkedDomains
        $classification = if ($isParked) { 'Parked' } else { 'Sending' }
        $dmarc = $null
        $source = $null
        $unavailable = $false
        $invalidCandidate = $null
        # DMARC policy discovery uses the domain, then its organisational domain only.
        $candidates = @($name, (Get-MtRegistrableDomain -DomainName $name)) | Select-Object -Unique
        foreach ($candidate in $candidates) {
            $found = ConvertFrom-MailAuthenticationRecordDmarc -DomainName $candidate
            if ($found -is [string]) {
                if ($found -like '*not available' -or $found -eq 'DNS lookup unavailable') { $unavailable = $true; break }
                if ($found -eq 'Invalid DMARC record') { $invalidCandidate = $candidate }
                continue
            }
            if ($null -ne $found -and $found -isnot [string]) {
                $dmarc = $found
                $source = $candidate
                break
            }
        }
        if ($unavailable) {
            [pscustomobject]@{ Domain = $name; Classification = $classification; Policy = 'Not checked'; Source = 'None'; Failed = 'DNS lookup not available'; Pass = $null }
            continue
        }
        $policy = $null
        if ($dmarc) {
            $policy = if ($source -ne $name -and $dmarc.policySubdomain) { $dmarc.policySubdomain } else { $dmarc.policy }
        }
        $checks = if ($isParked) {
            [ordered]@{
                'Record is valid' = $null -ne $dmarc -and $dmarc.valid
                'Parked-domain policy is reject' = $policy -eq 'reject'
            }
        } else {
            [ordered]@{
                'Record is valid' = $null -ne $dmarc -and $dmarc.valid
                'Policy is quarantine or reject' = $policy -in @('quarantine', 'reject')
                'Applies to 100 percent' = $null -eq $dmarc -or $dmarc.percentage -eq 100 -or $null -eq $dmarc.percentage
                'Aggregate reports (rua)' = @($dmarc.reportAggregate | Where-Object { $_.mailAddress }).Count -gt 0
                'Forensic reports (ruf)' = @($dmarc.reportForensic | Where-Object { $_.mailAddress }).Count -gt 0
            }
        }
        $failedChecks = @($checks.GetEnumerator() | Where-Object { -not $_.Value } | ForEach-Object { $_.Key })
        [pscustomobject]@{
            Domain         = $name
            Classification = $classification
            Policy         = if ($policy) { $policy } elseif ($invalidCandidate) { 'Invalid DMARC record' } else { 'No valid record' }
            Source         = if ($source) { $source } elseif ($invalidCandidate) { $invalidCandidate } else { 'None' }
            Failed         = $failedChecks -join ', '
            Pass           = $failedChecks.Count -eq 0
        }
    }
    $checked = @($report | Where-Object { $null -ne $_.Pass })
    $unchecked = @($report | Where-Object { $null -eq $_.Pass })
    $failed = @($checked | Where-Object { -not $_.Pass })
    if ($failed.Count -eq 0 -and $unchecked.Count -gt 0) {
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    }
    $testResult = $failed.Count -eq 0

    $passText = 'All accepted domains meet the applicable CIS DMARC requirement.'
    $failText = "$($failed.Count) domain(s) do not have a compliant DMARC policy."

    $resultMd = "| Domain | Classification | Applied policy | Record found at | Failed checks | Result |`n"
    $resultMd += "| --- | --- | --- | --- | --- | --- |`n"
    foreach ($row in $report) {
        $resultText = if ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }
        $resultMd += "| $($row.Domain) | $($row.Classification) | $($row.Policy) | $($row.Source) | $(if ($row.Failed) { $row.Failed } else { 'None' }) | $resultText |`n"
    }

    if ($testResult) {
        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
    } else {
        $testResultMarkdown = "$failText`n`n%TestResult%"
    }
    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd

    Add-MtTestResultDetail -Result $testResultMarkdown
    return $testResult
}

function Test-MtCisSpfRecordsPublished {
    <#
    .SYNOPSIS
        Checks the applicable CIS SPF requirement for each custom accepted domain.

    .DESCRIPTION
        Sending domains must publish an SPF record that ends with -all or ~all, directly or through a redirect. Domains listed in the ParkedDomains parameter must publish v=spf1 -all, which denies all senders. Every other domain gets the sending-domain audit. Domains in the onmicrosoft.com namespace are excluded because Microsoft manages their SPF.
        CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.8, L1)

    .EXAMPLE
        Test-MtCisSpfRecordsPublished

        Returns true if all custom domains meet the applicable CIS SPF requirement.

    .LINK
        https://maester.dev/docs/tests/CIS.M365.2.1.8
    #>
    [MaesterTest(
        Id = 'CIS.M365.2.1.8',
        Title = 'Ensure that SPF records are published for all Exchange Domains',
        Product = 'defender',
        Feature = 'email-authentication',
        Area = 'email-protection',
        ResourceType = 'Domain',
        Severity = 'Medium',
        UserImpact = 'Low',
        ImplementationCost = 'Medium',
        Mitre = ('T1566', 'T1684.002'),
        Control = ('cis-m365:2.1.8', 'nist-800-53-r5:SI-8'),
        Service = 'ExchangeOnline',
        Author = 'JeremyFinney-lgtm'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Domains that are not used to send email. They must publish v=spf1 -all.
        [string[]]$ParkedDomains = @()
    )

    Write-Verbose 'Getting accepted domains...'
    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.InitialDomain -eq $false -and $_.IsCoExistenceDomain -eq $false })

    $report = foreach ($domain in $domains) {
        $name = $domain.DomainName
        $isParked = Test-MtCisParkedDomain -DomainName $name -ParkedDomains $ParkedDomains
        $classification = if ($isParked) { 'Parked' } else { 'Sending' }
        $detail = ''
        $spf = ConvertFrom-MailAuthenticationRecordSpf -DomainName $name
        if ($spf -is [string] -and ($spf -like '*not available' -or $spf -eq 'DNS lookup unavailable')) {
            [pscustomobject]@{ Domain = $name; Record = $null; Classification = $classification; Pass = $null; Detail = 'DNS lookup not available' }
            continue
        }
        $record = if ($spf -and $spf.PSObject.Properties['record']) { $spf.record } else { $null }
        $effective = $record
        $redirectTargets = @()
        $redirectError = $null
        $redirectUnavailable = $false
        $visitedDomains = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $null = $visitedDomains.Add($name)

        while ($effective) {
            # RFC 7208 section 5.1: a redirect is ignored when the record has an all mechanism.
            $localAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all(\s|$)')
            if ($localAll.Success) { break }

            $redirect = [regex]::Match([string]$effective, '(?i)(?:^|\s)redirect=(?<target>[^\s;]+)')
            if (-not $redirect.Success) { break }
            $target = $redirect.Groups['target'].Value

            if ($redirectTargets.Count -ge 9) {
                $redirectError = 'The redirect chain exceeds the DNS lookup limit.'
                break
            }
            if (-not $visitedDomains.Add($target)) {
                $redirectError = "The redirect chain contains a cycle at $target."
                break
            }

            $redirectTargets += $target
            $redirected = ConvertFrom-MailAuthenticationRecordSpf -DomainName $target
            if ($redirected -is [string] -and ($redirected -like '*not available' -or $redirected -eq 'DNS lookup unavailable')) {
                $redirectUnavailable = $true
                break
            }
            $effective = if ($null -ne $redirected -and $redirected.PSObject.Properties['record']) { $redirected.record } else { $null }
            if (-not $effective) {
                $redirectError = "No SPF record was found at redirect target $target."
                break
            }
        }

        if ($redirectUnavailable) {
            [pscustomobject]@{ Domain = $name; Record = $record; Classification = $classification; Pass = $null; Detail = "DNS lookup not available for $($redirectTargets[-1])" }
            continue
        }
        $effectiveAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all\s*$')
        $pass = $effectiveAll.Success -and $effectiveAll.Groups['q'].Value -in '-', '~'
        if (-not $record) {
            $detail = 'No SPF record found'
        } elseif ($redirectError) {
            $detail = $redirectError
        } elseif ($redirectTargets.Count -gt 0 -and -not $pass) {
            $detail = "The effective record after redirecting to $($redirectTargets -join ' -> ') does not end with -all or ~all"
        } elseif ($redirectTargets.Count -gt 0) {
            $detail = "Redirects to $($redirectTargets -join ' -> ')"
        }
        elseif (-not $pass) {
            $detail = 'The record does not end with -all or ~all'
        }

        if ($isParked) {
            # CIS asks parked domains for v=spf1 -all: no sender mechanisms, no redirect, hard fail last.
            # An exp= modifier authorizes no one, so it is allowed before -all.
            $pass = [string]$record -match '(?i)^\s*v=spf1(\s+exp=\S+)*\s+-all\s*$'
            $detail = if ($pass) {
                'Listed as parked; the record denies all senders with -all.'
            } else {
                'Listed as parked; CIS requires v=spf1 -all, which denies all senders.'
            }
        }

        [pscustomobject]@{ Domain = $name; Record = $record; Classification = $classification; Pass = $pass; Detail = $detail }
    }

    $unchecked = @($report | Where-Object { $null -eq $_.Pass })
    $failed = @($report | Where-Object { $_.Pass -eq $false })
    if ($failed.Count -gt 0) {
        $testResult = $false
    } elseif ($unchecked.Count -gt 0) {
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    } else {
        $testResult = $true
    }

    $passText = if ($domains.Count -eq 0) { 'There are no custom domains, so no SPF records are required.' } else { 'All custom domains meet the applicable CIS SPF requirement.' }
    $failText = "$($failed.Count) custom domain(s) do not meet the applicable CIS SPF requirement."

    $resultMd = "| Domain | Classification | SPF record | Detail | Result |`n"
    $resultMd += "| --- | --- | --- | --- | --- |`n"
    foreach ($row in $report) {
        $resultText = if ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }
        $resultMd += "| $($row.Domain) | $($row.Classification) | $($row.Record) | $($row.Detail) | $resultText |`n"
    }

    if ($testResult) {
        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
    }
    else {
        $testResultMarkdown = "$failText`n`n%TestResult%"
    }
    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd

    Add-MtTestResultDetail -Result $testResultMarkdown
    return $testResult
}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

