1	# The mechanical half of the parameter naming rules ("Parameter names" in website/docs/writing-tests/attribute-rubric.md): every
2	# parameter of a built-in test or a pack that ships with Maester follows one convention, so an admin who
3	# sets a value in TestSettings can guess its name. Whether a name says what it measures is a judgement; the
4	# attribute-review workflow and the reviewer check that. Custom tests are not checked here.
5	
6	BeforeAll {
7	    Import-Module "$PSScriptRoot/../../Maester.psd1" -Force -WarningAction SilentlyContinue
8	    $script:repoRoot = (Resolve-Path "$PSScriptRoot/../../..").Path
9	
10	    $files = @(Get-ChildItem -Path (Join-Path $script:repoRoot 'tests'), (Join-Path $script:repoRoot 'packs') -Recurse -File -Filter 'Test.*.ps1' |
11	            Where-Object { $_.FullName -notmatch '[\\/]custom[\\/]' })
12	    $script:files = $files
13	    $tests = @(InModuleScope Maester -Parameters @{ Files = $files.FullName } {
14	            foreach ($file in $Files) { [pscustomobject](Read-MtNativeTest -Path $file -BuiltIn) }
15	        })
16	    $script:parameters = @(foreach ($t in $tests) {
17	            foreach ($p in @($t.Parameters | Where-Object { -not $_.EngineOwned })) {
18	                [pscustomobject]@{ Id = $t.Id; Name = $p.Name; Type = $p.Type; Setting = $p.Setting }
19	            }
20	        })
21	    $script:settings = InModuleScope Maester { (Get-MtSettingRegistry).Settings }
22	
23	    # Reports offenders as "ID: Name - detail" so a failure names every parameter to rename.
24	    function Get-Offender {
25	        param([scriptblock] $Where, [scriptblock] $Detail)
26	        @($script:parameters | Where-Object $Where | ForEach-Object { "$($_.Id): $($_.Name) - $(& $Detail $_)" } | Sort-Object -Unique)
27	    }
28	}
29	
30	Describe 'Names of test parameters' {
31	    It 'Finds the parameters of the built-in tests' {
32	        $script:parameters.Count | Should -BeGreaterThan 100
33	    }
34	
35	    It 'Uses PascalCase' {
36	        $offenders = Get-Offender { $_.Name -cnotmatch '^[A-Z][A-Za-z0-9]*$' } { 'start with a capital letter and use letters and digits only' }
37	        $offenders | Should -BeNullOrEmpty -Because 'parameter names are PascalCase, like PowerShell parameters'
38	    }
39	
40	    It 'Spells out Maximum and Minimum' {
41	        $offenders = Get-Offender { $_.Name -cmatch '^(Max|Min)(?!imum)' } {
42	            param($p) "rename to $($p.Name -creplace '^Max(?!imum)', 'Maximum' -creplace '^Min(?!imum)', 'Minimum')"
43	        }
44	        $offenders | Should -BeNullOrEmpty -Because 'a limit is named Maximum<What><Unit> or Minimum<What><Unit>, never Max or Min'
45	    }
46	
47	    It 'Ends a unit with a plain suffix' {
48	        $offenders = Get-Offender { $_.Name -cmatch 'In(Days|Hours|Minutes|Seconds)$' } {
49	            param($p) "rename to $($p.Name -creplace 'In(Days|Hours|Minutes|Seconds)$', '$1')"
50	        }
51	        $offenders | Should -BeNullOrEmpty -Because 'a unit is a plain suffix: MaximumLifetimeDays, not MaximumLifetimeInDays'
52	    }
53	
54	    It 'Names a list in the plural' {
55	        $offenders = Get-Offender { $_.Type -in 'string[]', 'object[]' -and $_.Name -cnotmatch 's$' } { 'a list takes a plural name, for example ParkedDomains' }
56	        $offenders | Should -BeNullOrEmpty -Because 'a string[] or object[] parameter holds several values, so its name is plural'
57	    }
58	
59	    It 'Avoids the names of PowerShell common parameters' {
60	        $reserved = 'Force', 'Confirm', 'WhatIf', 'PassThru'
61	        $offenders = Get-Offender { $_.Name -in $reserved } { 'name what turning it on does, for example AllDomains' }
62	        $offenders | Should -BeNullOrEmpty -Because 'these names mean something else in PowerShell'
63	    }
64	
65	    It 'Gives one name one type' {
66	        $offenders = @($script:parameters | Group-Object Name | Where-Object { @($_.Group.Type | Sort-Object -Unique).Count -gt 1 } | ForEach-Object {
67	                "$($_.Name): $(($_.Group | ForEach-Object { "$($_.Id) ($($_.Type))" }) -join ', ')"
68	            })
69	        $offenders | Should -BeNullOrEmpty -Because 'a name that holds a number on one test and a list on another means two different things; rename one'
70	    }
71	
72	    It 'Binds one name to one setting' {
73	        # A test may give a bound name a value of its own, but two tests that share a name and bind it must bind the same setting.
74	        $offenders = @($script:parameters | Where-Object Setting | Group-Object Name | Where-Object { @($_.Group.Setting | Sort-Object -Unique).Count -gt 1 } | ForEach-Object {
75	                "$($_.Name): $(($_.Group | ForEach-Object { "$($_.Id) ($($_.Setting))" }) -join ', ')"
76	            })
77	        $offenders | Should -BeNullOrEmpty -Because 'one parameter name has one meaning wherever it is bound'
78	    }
79	}
80	
81	Describe 'Settings that tests receive as parameters' {
82	    It 'Binds only registered settings or a pack''s own Namespace.Key settings' {
83	        $offenders = Get-Offender { $_.Setting -and -not $script:settings.ContainsKey($_.Setting) -and $_.Setting -notmatch '\.' } { "'$($_.Setting)' is not in assets/MaesterSettings.psd1" }
84	        $offenders | Should -BeNullOrEmpty
85	    }
86	
87	    It 'Leaves a bound setting to the engine instead of reading it in the test' {
88	        # A test that calls Get-MtSetting for a setting other tests receive as a parameter hides the value from
89	        # Get-MtTest and the results, and a TestSettings row cannot override it.
90	        $bound = @($script:parameters | Where-Object Setting | ForEach-Object Setting | Sort-Object -Unique)
91	        $offenders = foreach ($file in $script:files) {
92	            $ast = [System.Management.Automation.Language.Parser]::ParseFile($file.FullName, [ref]$null, [ref]$null)
93	            $testFunctions = $ast.FindAll({
94	                    param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
95	                    $node.Body.ParamBlock -and ($node.Body.ParamBlock.Attributes.TypeName.Name -match '^MaesterTest(Attribute)?$')
96	                }, $false)
97	            foreach ($function in $testFunctions) {
98	                $calls = $function.Body.FindAll({
99	                        param($node) $node -is [System.Management.Automation.Language.CommandAst] -and $node.GetCommandName() -in 'Get-MtSetting', 'Get-MtMaesterConfigGlobalSetting'
100	                    }, $true)
101	                foreach ($call in $calls) {
102	                    $name = @($call.CommandElements | Where-Object { $_ -is [System.Management.Automation.Language.StringConstantExpressionAst] -and $_.Value -ne $call.GetCommandName() } | ForEach-Object Value) | Select-Object -First 1
103	                    if ($name -and $name -in $bound) { "$($file.Name): reads '$name' with Get-MtSetting; declare [MaesterParameter(Setting = '$name')] instead" }
104	                }
105	            }
106	        }
107	        @($offenders) | Should -BeNullOrEmpty
108	    }
109	}
