1	function Test-MtCisDkim {
2	    <#
3	    .SYNOPSIS
4	    Checks DKIM for domains that send email and verifies parked domains have no DKIM records.
5	
6	    .DESCRIPTION
7	    Domains require DKIM to be enabled with a valid Exchange status. Domains listed in the ParkedDomains parameter must not publish DKIM records instead. Initial (MOERA) and coexistence domains are excluded, as Microsoft automatically signs outbound mail for those domains.
8	    CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.9, L1)
9	
10	    .EXAMPLE
11	    Test-MtCisDkim
12	
13	    Returns true if every domain has DKIM enabled with Exchange status Valid, and every domain listed in ParkedDomains has no selector1 or selector2 DKIM record. Initial and coexistence domains are excluded.
14	
15	    .LINK
16	    https://maester.dev/docs/commands/Test-MtCisDkim
17	    #>
18	    [MaesterTest(
19	        Id = 'CIS.M365.2.1.9',
20	        Title = 'Ensure that DKIM is enabled for all Exchange Online Domains',
21	        Product = 'defender',
22	        RelatedProduct = 'exchange',
23	        Feature = 'email-authentication',
24	        Area = 'email-protection',
25	        ResourceType = 'Domain',
26	        Severity = 'Medium',
27	        UserImpact = 'Low',
28	        ImplementationCost = 'Medium',
29	        Mitre = ('T1566', 'T1684.002'),
30	        Control = ('cis-m365:2.1.9', 'nist-800-53-r5:SC-8'),
31	        Service = 'ExchangeOnline',
32	        Author = 'NZLostboy',
33	        Contributor = ('JeanPhilippeGeorge', 'brianreidc7', 'amlhive-tech', 'JeremyFinney-lgtm')
34	    )]
35	    [CmdletBinding()]
36	    [OutputType([bool])]
37	    param(
38	        # Selector-name for the DKIM record to test..
39	        [string]$Selector = 'selector1',
40	
41	        # Domains that are not used to send email. They must not publish DKIM records.
42	        [string[]]$ParkedDomains = @()
43	    )
44	
45	    $dkimSigningConfigs = Get-MtExo -Request DkimSigningConfig
46	    $acceptedDomains = Get-MtExo -Request AcceptedDomain
47	
48	    $dkimRecords = @()
49	    foreach ($domain in $acceptedDomains) {
50	        if ($domain.InitialDomain -eq $true -or $domain.IsCoExistenceDomain -eq $true) {
51	            $dkimRecord = [PSCustomObject]@{
52	                domain     = $domain.DomainName
53	                classification = 'Excluded'
54	                pass       = 'Skipped'
55	                reason     = 'Initial or coexistence domain excluded from DKIM audit (Microsoft auto-signs outbound mail for this domain)'
56	                exchangeStatus = 'Excluded'
57	                dkimRecord = $null
58	            }
59	            $dkimRecords += $dkimRecord
60	            continue
61	        }
62	
63	        if (Test-MtCisParkedDomain -DomainName $domain.DomainName -ParkedDomains $ParkedDomains) {
64	            # CIS: don't publish DKIM records for a parked domain. Exchange Online uses selector1 and selector2.
65	            $selectorLookups = foreach ($selectorName in 'selector1', 'selector2') {
66	                foreach ($recordType in 'CNAME', 'TXT') {
67	                    Resolve-MtDnsRecord -Name "$selectorName._domainkey.$($domain.DomainName)" -Type $recordType
68	                }
69	            }
70	            $hasSelectorRecord = @($selectorLookups | Where-Object { @($_.Answers).Count -gt 0 }).Count -gt 0
71	            $incompleteLookups = @($selectorLookups | Where-Object { $_.Status -notin @('Success', 'NXDomain') })
72	            $resolverUnavailable = @($selectorLookups | Where-Object { $_.Status -ne 'NotAvailable' }).Count -eq 0
73	
74	            $pass, $reason = if ($hasSelectorRecord) {
75	                'Failed', 'Listed as parked, but a selector1 or selector2 DKIM record is published. Remove it.'
76	            } elseif ($resolverUnavailable) {
77	                'NotSupported', 'Listed as parked, but DNS lookups are not available here, so the DKIM records could not be checked.'
78	            } elseif ($incompleteLookups.Count -gt 0) {
79	                'Investigate', 'Listed as parked, but some DKIM selector lookups failed, so it could not be confirmed that no record is published.'
80	            } else {
81	                'Passed', 'Listed as parked, and no selector1 or selector2 DKIM record is published.'
82	            }
83	            $dkimRecords += [PSCustomObject]@{
84	                domain         = $domain.DomainName
85	                classification = 'Parked'
86	                pass           = $pass
87	                reason         = $reason
88	                exchangeStatus = 'Not applicable'
89	                dkimRecord     = $null
90	            }
91	            continue
92	        }
93	
94	        $dkimSigningConfig = $dkimSigningConfigs | Where-Object {
95	            $_.domain -eq $domain.domainname
96	        }
97	
98	        if (-not $dkimSigningConfig) {
99	            $dkimRecord = [PSCustomObject]@{
100	                domain     = $domain.DomainName
101	                classification = 'Sending'
102	                pass       = 'Failed'
103	                reason     = 'No DkimSigningConfig found. Add the domain to ParkedDomains if it does not send email.'
104	                exchangeStatus = 'Not configured'
105	                dkimRecord = $null
106	            }
107	            $dkimRecords += $dkimRecord
108	            continue
109	        }
110	
111	        if ((Get-Date) -gt $dkimSigningConfig.RotateOnDate) {
112	            if ($Selector -ne $dkimSigningConfig.SelectorAfterRotateOnDate) {
113	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorAfterRotateOnDate) based on EXO config"
114	            }
115	            $Selector = $dkimSigningConfig.SelectorAfterRotateOnDate
116	        } else {
117	            if ($Selector -ne $dkimSigningConfig.SelectorBeforeRotateOnDate) {
118	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorBeforeRotateOnDate) based on EXO config"
119	            }
120	            $selector = $dkimSigningConfig.SelectorBeforeRotateOnDate
121	        }
122	
123	        $isMicrosoftDomain = $domain.DomainName.EndsWith(".onmicrosoft.com")
124	        $isMicrosoftExoHybridDomain = $domain.DomainName.EndsWith(".mail.onmicrosoft.com")
125	        $dkimDnsName = if ($isMicrosoftExoHybridDomain) {
126	            "$($Selector)._domainkey.$($domain.DomainName)"
127	        } elseif ($isMicrosoftDomain) {
128	            $dkimSigningConfig."$($selector)CNAME"
129	        } else {
130	            "$($Selector)._domainkey.$($domain.DomainName)"
131	        }
132	        $dkimRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -DkimDnsName $dkimDnsName -Records DKIM
133	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'pass' -Value 'Failed'
134	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'reason' -Value ''
135	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'exchangeStatus' -Value $dkimSigningConfig.Status
136	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'classification' -Value 'Sending'
137	
138	        if (-not $dkimSigningConfig.enabled) {
139	            $dkimRecord.pass = 'Failed'
140	            $dkimRecord.reason = 'DKIM is disabled'
141	        } elseif ($dkimSigningConfig.Status -ne 'Valid') {
142	            $dkimRecord.pass = 'Failed'
143	            $dkimRecord.reason = "Exchange DKIM status is '$($dkimSigningConfig.Status)' (expected Valid)"
144	        } elseif ($null -ne $dkimRecord.dkimRecord -and $dkimRecord.dkimRecord.GetType().Name -eq 'DKIMRecord') {
145	            if (-not $dkimRecord.dkimRecord.validBase64) {
146	                $dkimRecord.reason = 'Malformed public key'
147	            } else {
148	                $dkimRecord.pass = 'Passed'
149	            }
150	        } elseif ($domain.DomainName -like '*.onmicrosoft.com') {
151	            $dkimRecord.reason = "Recommendation: Disable sending from domain"
152	        } elseif ($dkimRecord.dkimRecord -like '*not available') {
153	            $dkimRecord.pass = 'NotSupported'
154	            $dkimRecord.reason = $dkimRecord.dkimRecord
155	        } else {
156	            $dkimRecord.reason = $dkimRecord.dkimRecord
157	        }
158	
159	        $dkimRecords += $dkimRecord
160	    }
161	
162	    if ('Failed' -in $dkimRecords.pass) {
163	        $testResult = $false
164	    }
165	    elseif ('Investigate' -in $dkimRecords.pass) {
166	        $testResult = $true
167	    }
168	    elseif ('NotSupported' -in $dkimRecords.pass -and 'Passed' -notin $dkimRecords.pass) {
169	        Add-MtTestResultDetail -SkippedBecause NotSupported
170	        return $null
171	    }
172	    elseif ('Passed' -notin $dkimRecords.pass) {
173	        Add-MtTestResultDetail -SkippedBecause NotApplicable
174	        return $null
175	    }
176	    else {
177	        $testResult = $true
178	    }
179	
180	    $portalLink = 'https://security.microsoft.com/authentication?viewid=DKIM'
181	
182	    if ($testResult -and ('Investigate' -in $dkimRecords.pass -or 'NotSupported' -in $dkimRecords.pass)) {
183	        $testResultMarkdown = "Compliance with the applicable CIS DKIM requirement remains unconfirmed. Review the domains marked Investigate or skipped because DNS lookups are unavailable.`n`n%TestResult%"
184	    }
185	    elseif ($testResult) {
186	        $testResultMarkdown = "Well done. Sending domains have DKIM configured and valid records exist, and parked domains have no known Exchange selector records.`n`n%TestResult%"
187	    } else {
188	        $testResultMarkdown = "Your tenant's domains do not have DKIM fully deployed. Review [EXO configuration]($portalLink) and DNS records.`n`n%TestResult%"
189	    }
190	
191	    $passResult = '✅ Pass'
192	    $failResult = '❌ Fail'
193	    $skipResult = '🗄️ Skip'
194	    $result = "| Domain | Classification | Result | Exchange status | Reason |`n"
195	    $result += "| --- | --- | --- | --- | --- |`n"
196	    foreach ($item in $dkimRecords | Sort-Object -Property domain) {
197	        switch ($item.pass) {
198	            'Passed' { $itemResult = $passResult }
199	            'Skipped' { $itemResult = $skipResult }
200	            'NotSupported' { $itemResult = $skipResult }
201	            'Failed' { $itemResult = $failResult }
202	            'Investigate' { $itemResult = '🔎 Investigate' }
203	        }
204	        $result += "| $($item.domain) | $($item.classification) | $($itemResult) | $($item.exchangeStatus) | $($item.reason) |`n"
205	    }
206	
207	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $result
208	
209	    Add-MtTestResultDetail -Result $testResultMarkdown -Investigate:('Investigate' -in $dkimRecords.pass -and 'Failed' -notin $dkimRecords.pass)
210	    return $testResult
211	}
