assert m, 'generate import'
names = [n.strip() for n in m.group(1).split(',') if n.strip()]
for extra in ['PARAMETER_TYPES', 'emptyParameter', 'parameterForSetting', 'resolveParameter', 'settingOf', 'buildConfigExample', 'scaffoldedSettings']:
