component = r'''// Parameters: the values an administrator can change. One card per parameter. A parameter bound to a registered
// setting takes its type, default and allowed values from the registry, so only its name and description are typed.
function ParameterBuilder({ parameters, builtin, onChange }) {
  const update = (index, patch) => onChange(parameters.map((p, i) => (i === index ? { ...p, ...patch } : p)));
  const remove = (index) => onChange(parameters.filter((_, i) => i !== index));
  const bindable = data.settings.filter((s) => !s.connection && s.type !== "object");
  const unused = bindable.filter((s) => !parameters.some((p) => settingOf(p, data) === s));
  return (
    <div className={styles.stack}>
      <datalist id="parameter-names">
        {data.parameterNames.map((n) => (
          <option key={n.name} value={n.name}>
            {n.type}
          </option>
        ))}
      </datalist>
      {parameters.map((raw, index) => {
        const p = resolveParameter(raw, data);
        const setting = settingOf(raw, data);
        const used = data.parameterNames.find((n) => n.name.toLowerCase() === p.name.trim().toLowerCase());
        return (
          <div className={styles.group} key={index}>
            <div className={styles.groupRow}>
              <Input
                id={index === 0 ? "input-parameters" : undefined}
                aria-label="Parameter name"
                list="parameter-names"
                placeholder="Name, for example MaximumInactiveDays"
                value={raw.name}
                onChange={(e) => update(index, { name: e.target.value.replace(/\s/g, "") })}
              />
              {setting ? (
                <Badge>{setting.type}</Badge>
              ) : (
                <Select value={raw.type} onValueChange={(v) => update(index, { type: v })} placeholder="Type" options={PARAMETER_TYPES.map((t) => ({ value: t, label: t }))} />
              )}
              <Button variant="ghost" onClick={() => remove(index)}>
                <DeleteIcon />
                Remove
              </Button>
            </div>
            <Input aria-label="Description" placeholder="One line: what the value changes" value={raw.description} onChange={(e) => update(index, { description: e.target.value.replace(/[\r\n]/g, " ") })} />
            {setting ? (
              <p className={styles.hint}>
                Bound to the setting <code>{setting.name}</code>, which an administrator sets once in <code>GlobalSettings</code>. Its type
                {p.default ? ", default (" + p.default + ")" : ""}
                {p.allowedValues.length ? " and allowed values (" + p.allowedValues.join(", ") + ")" : ""} come from the settings registry.
              </p>
            ) : (
              <>
                <div className={styles.groupRow}>
                  {raw.type !== "switch" && (
                    <Input
                      aria-label="Default"
                      placeholder={raw.type === "int" ? "Default, for example 90" : raw.type === "bool" ? "Default: true or false" : raw.type === "string[]" ? "Default values, separated by commas (empty for none)" : "Default (empty for none)"}
                      value={raw.default}
                      onChange={(e) => update(index, { default: e.target.value })}
                    />
                  )}
                  {raw.type === "int" && (
                    <>
                      <Input aria-label="Lowest value" placeholder="Lowest, for example 1" value={raw.min} onChange={(e) => update(index, { min: e.target.value })} />
                      <Input aria-label="Highest value" placeholder="Highest, for example 365" value={raw.max} onChange={(e) => update(index, { max: e.target.value })} />
                    </>
                  )}
                  {raw.type === "switch" && <p className={styles.hint}>A switch is off by default. Name it after what turning it on does.</p>}
                </div>
                {(raw.type === "string" || raw.type === "string[]") && (
                  <div className={styles.groupRow}>
                    <Input aria-label="Allowed values" placeholder="Allowed values, separated by commas (empty for any)" value={raw.allowed} onChange={(e) => update(index, { allowed: e.target.value })} />
                    <Select
                      value={raw.kind || "none"}
                      onValueChange={(v) => update(index, { kind: v === "none" ? "" : v })}
                      placeholder="Holds"
                      options={[{ value: "none", label: "Plain text" }].concat(data.parameterKinds.map((k) => ({ value: k, label: k })))}
                    />
                  </div>
                )}
                {!builtin && (
                  <Input aria-label="Setting" placeholder="Shared setting of your own, for example Contoso.Regions (optional)" value={raw.setting} onChange={(e) => update(index, { setting: e.target.value.trim() })} />
                )}
              </>
            )}
            {used && !setting && used.type === p.type && (
              <p className={styles.hint}>
                {used.tests} built-in {used.tests === 1 ? "test uses" : "tests use"} <code>{used.name}</code>. Reuse the name only if it means the same thing here.
              </p>
            )}
          </div>
        );
      })}
      <div className={styles.groupRow}>
        <Select
          value=""
          onValueChange={(v) => onChange([...parameters, parameterForSetting(data.settings.find((s) => s.name === v))])}
          placeholder="Add a shared setting"
          options={unused.map((s) => ({ value: s.name, label: s.name, hint: s.description }))}
        />
        <Button onClick={() => onChange([...parameters, { ...emptyParameter }])}>
          <PlusIcon />
          Add a parameter
        </Button>
      </div>
    </div>
  );
}

'''
