                      <Button variant="ghost" size="icon" aria-label={"Remove " + c} title="Remove" onClick={() => set({ controls: state.controls.filter((x) => x !== c) })}>
                        <DeleteIcon />
                      </Button>
                    </li>
                  );
                })}
              </ul>
            )}
          </Field>
        </section>

        <section className={styles.section}>
