.builder {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 2rem;
  align-items: start;
}

.form {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.section {
  border: 1px solid var(--ifm-color-emphasis-200);
  border-radius: 12px;
  background: var(--ifm-background-surface-color);
  padding: 1.25rem 1.25rem 0.5rem;
}

.section h2 {
  font-size: 1.2rem;
  margin-bottom: 1rem;
