import re
base = 'website/src/components/TestBuilder/'

# ---- ui.jsx: a compact radio row
p = base + 'ui.jsx'
s = open(p).read()
anchor = "export function Checkbox({"
assert s.count(anchor) == 1
s = s.replace(anchor, '''// A radio group as one row of choices. Only the selected option's text is shown, under the row.
export function RadioPills({ value, onValueChange, options, label }) {
  const picked = options.find((o) => o.value === value);
  return (
    <div className={ui.pillsWrap}>
      <RadioGroupPrimitive.Root className={ui.pills} value={value} onValueChange={onValueChange} aria-label={label}>
        {options.map((o) => (
          <RadioGroupPrimitive.Item key={o.value} value={o.value} className={ui.pill} title={o.text}>
            {o.label || o.value}
          </RadioGroupPrimitive.Item>
        ))}
      </RadioGroupPrimitive.Root>
      {picked && picked.text && <p className={ui.pillText}>{picked.text}</p>}
    </div>
  );
}

''' + anchor)
open(p, 'w').write(s)

p = base + 'ui.module.css'
s = open(p).read()
s += '''
/* A radio group as one row of choices. */
.pillsWrap { display: flex; flex-direction: column; gap: 0.4rem; width: 100%; }
.pills { display: flex; flex-wrap: wrap; gap: 0.2rem; padding: 0.2rem; border-radius: 8px; background: var(--ifm-color-emphasis-200); width: fit-content; max-width: 100%; }
.pill { border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--ifm-color-emphasis-800); font: inherit; font-size: 0.875rem; font-weight: 500; padding: 0.3rem 0.85rem; cursor: pointer; transition: background 0.15s, color 0.15s; }
.pill:hover { background: var(--ifm-color-emphasis-100); }
.pill[data-state="checked"] { background: var(--ifm-background-color); border-color: var(--ifm-color-primary); color: var(--ifm-font-color-base); font-weight: 600; }
.pill:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--ifm-color-primary) 25%, transparent); }
.pillText { margin: 0; font-size: 0.83rem; color: var(--ifm-color-emphasis-700); }
'''
open(p, 'w').write(s)

# ---- index.jsx
p = base + 'index.jsx'
s = open(p).read()
def swap(old, new, count=1):
    global s
    assert s.count(old) == count, (old[:70], s.count(old))
    s = s.replace(old, new)

swap('import React, { useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";',
     'import React, { useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";\nimport { createPortal } from "react-dom";')
swap('RadioCards, Select,', 'RadioCards, RadioPills, Select,')

swap('''export default function TestBuilder() {''', '''// The form is shown one step at a time. Each step lists the fields whose problems count against it.
const STEPS = [
  { key: "start", label: "Who it is for", fields: [] },
  { key: "name", label: "Name", fields: ["suite", "prefix", "id", "title", "functionName"] },
  { key: "about", label: "Subject", fields: ["product", "feature", "relatedProducts", "area", "resourceType"] },
  { key: "priority", label: "Priority", fields: ["severity", "userImpact", "implementationCost"] },
  { key: "mapping", label: "Mapping", fields: ["mitre", "control"] },
  { key: "requirements", label: "Requirements", fields: ["services", "license", "permission", "tenantType", "cloud", "platform"] },
  { key: "parameters", label: "Parameters", fields: ["parameters"] },
  { key: "lifecycle", label: "Lifecycle and credit", fields: ["lifecycle", "replacedBy", "flags", "author", "contributor", "tags"] },
];
const stepOfField = (field) => (STEPS.find((s) => s.fields.includes(field)) || STEPS[0]).key;
const stepOfHash = (hash) => {
  const value = (hash || "").replace(/^#/, "");
  if (value.startsWith("field-")) return stepOfField(value.slice(6));
  return STEPS.some((s) => s.key === value) ? value : null;
};

// The list of steps: in the site's sidebar on a wide screen, a row above the form on a narrow one. A step shows
// a tick once it has been opened and has nothing to fix, or the number of things to fix.
function StepList({ steps, step, onStep, className }) {
  return (
    <ol className={className} aria-label="Steps">
      {steps.map((s, index) => (
        <li key={s.key}>
          <button type="button" className={styles.step} aria-current={s.key === step ? "step" : undefined} onClick={() => onStep(s.key)}>
            <span className={styles.stepMark} data-state={s.errors ? "bad" : s.done ? "done" : "todo"} aria-hidden="true">
              {s.errors ? s.errors : s.done ? "✓" : index + 1}
            </span>
            <span className={styles.stepLabel}>{s.label}</span>
            {s.optional && <span className={styles.stepNote}>Optional</span>}
            {s.errors > 0 && (
              <span className={styles.srOnly}>
                , {s.errors} to fix
              </span>
            )}
          </button>
        </li>
      ))}
    </ol>
  );
}

export default function TestBuilder() {''')

swap('''  const [tab, setTab] = useState("ps1");
  const [helpId, setHelpId] = useState(null);''', '''  const [tab, setTab] = useState("ps1");
  const [step, setStepState] = useState("start");
  const [seen, setSeen] = useState(["start"]);
  const [railHost, setRailHost] = useState(null);
  const formRef = useRef(null);
  const [helpId, setHelpId] = useState(null);''')

swap('''  const need = (name) => builtin && P[name].required !== "No";
''', '''  const need = (name) => builtin && P[name].required !== "No";

  // Steps. The address keeps the step, so a link or a reload opens it; a link to a field opens the field's step.
  const setStep = useCallback((key, field) => {
    setStepState(key);
    setSeen((list) => (list.includes(key) ? list : [...list, key]));
    setHelpId(null);
    try {
      window.history.replaceState(null, "", "#" + key);
    } catch (e) {
      // The address is not updated; the step still opens.
    }
    requestAnimationFrame(() => {
      const target = field ? document.getElementById("field-" + field) : formRef.current;
      if (!target) return;
      if (field) target.scrollIntoView({ block: "center" });
      else if (target.getBoundingClientRect().top < 0) target.scrollIntoView({ block: "start" });
      const input = field && document.getElementById("input-" + field);
      if (input && input.focus) input.focus({ preventScroll: true });
    });
  }, []);
  const goField = (field) => setStep(stepOfField(field), field);
  useEffect(() => {
    setRailHost(document.getElementById("mt-builder-steps"));
    const open = () => {
      const hash = window.location.hash;
      const key = stepOfHash(hash);
      if (key) setStep(key, hash.startsWith("#field-") ? hash.slice(7) : undefined);
    };
    open();
    window.addEventListener("hashchange", open);
    return () => window.removeEventListener("hashchange", open);
  }, [setStep]);
  const steps = STEPS.map((s) => {
    const count = errors.filter((p) => s.fields.includes(p.field)).length;
    return { ...s, errors: count, done: seen.includes(s.key) && count === 0 && s.key !== step, optional: !builtin && !["start", "name"].includes(s.key) };
  });
  const stepIndex = STEPS.findIndex((s) => s.key === step);
''')

# sections, in order
keys = ['start', 'name', 'about', 'priority', 'mapping', 'requirements', 'parameters', 'lifecycle']
parts = s.split('<section className={styles.section}>')
assert len(parts) == 9, len(parts)
out = parts[0]
for k, part in zip(keys, parts[1:]):
    out += '<section className={styles.section} id={"step-" + "%s"} hidden={step !== "%s"}>' % (k, k) + part
s = out

swap('''      <div className={styles.form}>
        <section''', '''      <div className={styles.form} ref={formRef}>
        <StepList steps={steps} step={step} onStep={setStep} className={styles.stepStrip} />
        <section''')

swap('''        </section>
      </div>

      <aside className={styles.output}''', '''        </section>
        <div className={styles.stepNav}>
          <Button disabled={stepIndex === 0} onClick={() => setStep(STEPS[stepIndex - 1].key)}>
            Back
          </Button>
          <span className={styles.stepCount}>
            Step {stepIndex + 1} of {STEPS.length}
          </span>
          {stepIndex < STEPS.length - 1 ? (
            <Button variant="primary" onClick={() => setStep(STEPS[stepIndex + 1].key)}>
              Next: {STEPS[stepIndex + 1].label}
            </Button>
          ) : (
            <span className={styles.stepCount}>{errors.length ? "Fix what is listed with the code, then copy it." : "Done. Copy the code."}</span>
          )}
        </div>
      </div>
      {railHost && createPortal(<StepList steps={steps} step={step} onStep={setStep} className={styles.stepRail} />, railHost)}

      <aside className={styles.output}''')

swap('''                    <a href={"#field-" + p.field}>{p.text}</a>''', '''                    <a
                      href={"#field-" + p.field}
                      onClick={(e) => {
                        e.preventDefault();
                        goField(p.field);
                      }}
                    >
                      {p.text}
                    </a>''')

for f in ['severity', 'userImpact', 'implementationCost', 'lifecycle']:
    swap('<RadioCards label="%s"' % f, '<RadioPills label="%s"' % f)
open(p, 'w').write(s)

p = base + 'styles.module.css'
s = open(p).read()
s += '''
/* Steps: a list in the site's sidebar on a wide screen, a row above the form on a narrow one. */
.stepRail, .stepStrip { list-style: none; margin: 0; padding: 0; }
.stepRail { display: flex; flex-direction: column; gap: 0.1rem; }
.stepStrip { display: none; gap: 0.3rem; overflow-x: auto; padding-bottom: 0.3rem; }
.step { display: flex; align-items: center; gap: 0.55rem; width: 100%; padding: 0.35rem 0.5rem; border: 0; border-radius: 6px; background: transparent; color: var(--ifm-color-emphasis-800); font: inherit; font-size: 0.875rem; text-align: left; cursor: pointer; }
.step:hover { background: var(--ifm-color-emphasis-100); }
.step[aria-current="step"] { background: color-mix(in srgb, var(--ifm-color-primary) 10%, transparent); color: var(--ifm-font-color-base); font-weight: 600; }
.step:focus-visible { outline: 2px solid var(--ifm-color-primary); outline-offset: 1px; }
.stepMark { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 1.35rem; height: 1.35rem; border-radius: 999px; border: 1px solid var(--ifm-color-emphasis-400); font-size: 0.72rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.step[aria-current="step"] .stepMark { border-color: var(--ifm-color-primary); }
.stepMark[data-state="done"] { border-color: var(--ifm-color-success-dark); color: var(--ifm-color-success-dark); }
.stepMark[data-state="bad"] { border-color: var(--ifm-color-danger-dark); background: var(--ifm-color-danger-dark); color: #fff; }
.stepLabel { min-width: 0; }
.stepNote { margin-left: auto; font-size: 0.7rem; font-weight: 400; color: var(--ifm-color-emphasis-600); }
.stepStrip .step { width: auto; white-space: nowrap; border: 1px solid var(--ifm-color-emphasis-300); }
.stepStrip .stepNote { display: none; }
.stepNav { display: flex; align-items: center; justify-content: space-between; gap: 0.75rem; flex-wrap: wrap; }
.stepCount { font-size: 0.83rem; color: var(--ifm-color-emphasis-700); }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
/* Below this width the sidebar is a drawer, so the steps move above the form. */
@media (max-width: 49.99rem) {
  .stepRail { display: none; }
  .stepStrip { display: flex; }
}
'''
open(p, 'w').write(s)

# ---- Sidebar: a place for the steps on the test builder page
p = 'website/src/components/overrides/Sidebar.astro'
s = open(p).read()
old = "const topics = (Astro.locals.starlightSidebarTopics"
assert s.count(old) == 1
s = s.replace(old, """// The test builder lists its steps here (TestBuilder/index.jsx renders them into the element below), above the
// guides on writing tests. The link to the builder itself is the page you are on, so it is left out.
const isBuilder = Astro.url.pathname.replace(/\\/$/, '') === '/test-builder';
if (isBuilder) sidebar = sidebar.filter((entry) => !(entry.type === 'link' && entry.isCurrent));
""" + old)
old = "<SidebarPersister>\n"
assert s.count(old) == 1
s = s.replace(old, """{
	isBuilder && (
		<div class="mt-builder-steps">
			<p class="mt-builder-steps__title">Steps</p>
			<div id="mt-builder-steps" />
		</div>
	)
}
""" + old)
open(p, 'w').write(s)
print('ok')

